# Hindi / Gujarati text for Geography Ch 3 lesson, sections 4-5.
TEXT_B = {
 "s4.thm.title": ("पारंपरिक ज्ञान और आधुनिक पुनरुद्धार", "પરંપરાગત જ્ઞાન અને આધુનિક પુનરુત્થાન"),
 "s4.thm.body": (
  "बहुउद्देशीय परियोजनाओं के नुक़सानों को देखते हुए कई लोगों का मानना है कि **वर्षा जल संग्रहण** सामाजिक-आर्थिक और पर्यावरणीय दृष्टि से एक व्यवहार्य विकल्प है। प्राचीन भारत में लोगों को वर्षा पद्धति और मृदा के गुणों का गहरा ज्ञान था, और उन्होंने स्थानीय पारिस्थितिकी के अनुसार **वर्षा जल, भौम जल, नदी जल और बाढ़ जल** संग्रहण की अनेक विधियाँ विकसित कीं।\n\n"
  "- **पहाड़ी और पर्वतीय क्षेत्रों** में लोगों ने **पश्चिमी हिमालय** में **'गुल' अथवा 'कुल'** जैसी वाहिकाएँ, नदी की धारा का रास्ता बदलकर, खेतों में सिंचाई के लिए बनाईं।\n"
  "- पीने का जल इकट्ठा करने के लिए, विशेषकर **राजस्थान** में, **छत वर्षा जल संग्रहण** का तरीक़ा आम था।\n"
  "- **बंगाल के बाढ़ के मैदानों** में लोग खेतों की सिंचाई के लिए **बाढ़ जल वाहिकाएँ** बनाते थे।\n"
  "- **शुष्क और अर्ध-शुष्क क्षेत्रों** में खेतों को वर्षा जल भंडारण क्षेत्रों में बदल दिया जाता था, जिससे जल रुककर मिट्टी को नम कर सके, जैसे **जैसलमेर में 'खादीन'** और राजस्थान के अन्य भागों में **'जोहड़'**।\n\n"
  "**राजस्थान के टाँके:** राजस्थान के अर्ध-शुष्क और शुष्क क्षेत्रों, विशेषकर **बीकानेर, फलोदी और बाड़मेर** में, लगभग हर घर में पीने का पानी इकट्ठा करने के लिए **भूमिगत टैंक अथवा 'टाँका'** हुआ करते थे। इनका आकार एक बड़े कमरे जितना हो सकता था; **फलोदी** में एक घर में **6.1 मीटर गहरा, 4.27 मीटर लंबा और 2.44 मीटर चौड़ा** टाँका था। "
  "टाँका सुविकसित छत वर्षा जल संग्रहण तंत्र का अभिन्न हिस्सा होता था, जिसे मुख्य घर या आँगन में बनाया जाता था, और **ढलवाँ छतों** से पाइप द्वारा जोड़ा जाता था। छत से वर्षा का पानी इन पाइपों से होकर टाँका तक पहुँचता था। **पहली बारिश** का पानी **इकट्ठा नहीं** किया जाता था, क्योंकि इससे छत और पाइप साफ़ होते थे। "
  "टाँकों में इकट्ठा वर्षा जल अन्य सभी स्रोतों के सूख जाने पर भी पीने के पानी का भरोसेमंद स्रोत होता है, और इसे प्राकृतिक जल का शुद्धतम रूप, **'पालर पानी'**, माना जाता है। कई घरों में गर्मी से बचने के लिए टाँकों के साथ भूमिगत कमरे बनाए जाते थे, क्योंकि टाँका कमरे को **ठंडा** रखता था। "
  "आज पश्चिमी राजस्थान में **इंदिरा गांधी नहर** से बारहमासी पेयजल उपलब्ध होने के कारण यह प्रथा घट रही है, हालाँकि कुछ घर आज भी टाँके रखते हैं क्योंकि उन्हें नल के पानी का स्वाद पसंद नहीं।\n\n"
  "**आधुनिक पुनरुद्धार:**\n"
  "- **मैसूरु (कर्नाटक)** के दूरस्थ गाँव **गेंदाथूर** में लगभग **200 घरों** ने छत वर्षा जल संग्रहण तंत्र लगाए हैं, और गाँव वर्षा जल से समृद्ध होने के लिए जाना जाता है।\n"
  "- **शिलांग, मेघालय:** लगभग 55 किमी दूर स्थित चेरापूँजी और मॉसिनराम में विश्व की सबसे अधिक वर्षा होती है, फिर भी शहर में पानी की भारी कमी है; लगभग हर घर में छत वर्षा जल संग्रहण है, जिससे कुल जल आवश्यकता का लगभग **15-25 प्रतिशत** पूरा होता है।\n"
  "- **तमिलनाडु** भारत का **पहला राज्य** है जिसने पूरे राज्य में सभी घरों के लिए **छत वर्षा जल संग्रहण अनिवार्य** किया, और दोषियों को सज़ा देने के क़ानूनी प्रावधान हैं।\n"
  "- **मेघालय में बाँस ड्रिप सिंचाई:** लगभग **200 वर्ष पुरानी** प्रणाली, जिसमें नदियों और झरनों के जल को **बाँस से बने पाइपों** द्वारा एकत्र किया जाता है। प्रति मिनट लगभग **18-20 लीटर** जल बाँस पाइप में प्रवेश करता है, सैकड़ों मीटर दूर ले जाया जाता है, और पौधे की जगह पर घटकर **20-80 बूँद प्रति मिनट** रह जाता है।\n"
  "- **प्रधानमंत्री कृषि सिंचाई योजना (2015):** हर खेत तक सिंचाई पहुँचाने ('**हर खेत को पानी**') और बेहतर सिंचाई तथा जल संरक्षण से जल उपयोग दक्षता बढ़ाने ('**प्रति बूँद अधिक फ़सल**') की केंद्रीय योजना।",
  "બહુહેતુક યોજનાઓનાં નુકસાનો જોતાં ઘણા માને છે કે **વરસાદી જળ સંગ્રહ** સામાજિક-આર્થિક અને પર્યાવરણીય દૃષ્ટિએ યોગ્ય વિકલ્પ છે. પ્રાચીન ભારતમાં લોકોને વરસાદની ભાત અને જમીનના પ્રકારોનું ઊંડું જ્ઞાન હતું, અને તેમણે સ્થાનિક પરિસ્થિતિ મુજબ **વરસાદી પાણી, ભૂગર્ભજળ, નદીનું પાણી અને પૂરનું પાણી** સંગ્રહવાની અનેક રીતો વિકસાવી.\n\n"
  "- **પહાડી અને પર્વતીય વિસ્તારો**માં લોકોએ **પશ્ચિમ હિમાલય**માં **'ગુલ' કે 'કુલ'** જેવી નાળો, નદીનો પ્રવાહ વાળીને, ખેતી માટે બનાવી.\n"
  "- પીવાનું પાણી સંગ્રહવા, ખાસ કરીને **રાજસ્થાન**માં, **છાપરા પરથી વરસાદી પાણીનો સંગ્રહ** સામાન્ય હતો.\n"
  "- **બંગાળનાં પૂરનાં મેદાનો**માં લોકો ખેતરોની સિંચાઈ માટે **પૂરના પાણીની નહેરો** બનાવતા.\n"
  "- **શુષ્ક અને અર્ધશુષ્ક વિસ્તારો**માં ખેતરોને વરસાદી પાણીના સંગ્રહ સ્થાનોમાં ફેરવવામાં આવતાં, જેથી પાણી રોકાઈને જમીનને ભેજવાળી કરે, જેમ કે **જેસલમેરમાં 'ખડીન'** અને રાજસ્થાનના અન્ય ભાગોમાં **'જોહડ'**.\n\n"
  "**રાજસ્થાનનાં ટાંકાં:** રાજસ્થાનના અર્ધશુષ્ક અને શુષ્ક વિસ્તારોમાં, ખાસ કરીને **બિકાનેર, ફલોદી અને બાડમેર**માં, લગભગ દરેક ઘરમાં પીવાનું પાણી સંગ્રહવા **ભૂગર્ભ ટાંકી કે 'ટાંકું'** રહેતું. તેનું કદ એક મોટા ઓરડા જેટલું હોઈ શકતું; **ફલોદી**માં એક ઘરમાં **6.1 મીટર ઊંડું, 4.27 મીટર લાંબું અને 2.44 મીટર પહોળું** ટાંકું હતું. "
  "ટાંકું સુવિકસિત છાપરા વરસાદી જળ સંગ્રહ પ્રણાલીનો ભાગ હતું, જે મુખ્ય ઘર કે આંગણામાં બનાવાતું, અને **ઢાળવાળાં છાપરાં** સાથે પાઇપથી જોડાતું. છાપરા પર પડતો વરસાદ પાઇપ દ્વારા ટાંકામાં પહોંચતો. **પહેલા વરસાદ**નું પાણી **સંગ્રહાતું નહિ**, કારણ કે તેનાથી છાપરું અને પાઇપ સાફ થતાં. "
  "ટાંકામાં સંગ્રહેલું વરસાદી પાણી બીજા બધા સ્રોતો સુકાઈ જાય ત્યારે પણ પીવાના પાણીનો ભરોસાપાત્ર સ્રોત છે, અને તેને કુદરતી પાણીનું શુદ્ધતમ સ્વરૂપ, **'પાલર પાણી'**, ગણાય છે. ઘણાં ઘરોમાં ગરમીથી બચવા ટાંકાની બાજુમાં ભૂગર્ભ ઓરડા બનાવાતા, કારણ કે ટાંકું ઓરડાને **ઠંડો** રાખતું. "
  "આજે પશ્ચિમ રાજસ્થાનમાં **ઇન્દિરા ગાંધી નહેર**થી બારમાસી પાણી ઉપલબ્ધ થતાં આ પ્રથા ઘટી રહી છે, જોકે કેટલાંક ઘરો હજી ટાંકાં રાખે છે કારણ કે તેમને નળના પાણીનો સ્વાદ ગમતો નથી.\n\n"
  "**આધુનિક પુનરુત્થાન:**\n"
  "- **મૈસૂરુ (કર્ણાટક)**ના અંતરિયાળ ગામ **ગેંડાથુર**માં આશરે **200 ઘરોએ** છાપરા વરસાદી જળ સંગ્રહ પ્રણાલી લગાવી છે, અને ગામ વરસાદી પાણીથી સમૃદ્ધ હોવા માટે જાણીતું છે.\n"
  "- **શિલોંગ, મેઘાલય:** આશરે 55 કિમી દૂર આવેલાં ચેરાપુંજી અને માવસિનરામમાં વિશ્વનો સૌથી વધુ વરસાદ પડે છે, છતાં શહેરમાં પાણીની ભારે અછત છે; લગભગ દરેક ઘરમાં છાપરા જળ સંગ્રહ છે, જેનાથી કુલ પાણીની જરૂરિયાતના આશરે **15-25 ટકા** પૂરા થાય છે.\n"
  "- **તમિળનાડુ** ભારતનું **પહેલું રાજ્ય** છે જેણે આખા રાજ્યમાં બધાં ઘરો માટે **છાપરા વરસાદી જળ સંગ્રહ ફરજિયાત** બનાવ્યો, અને ભંગ કરનારને સજાની કાનૂની જોગવાઈ છે.\n"
  "- **મેઘાલયમાં વાંસ ટપક સિંચાઈ:** આશરે **200 વર્ષ જૂની** પ્રણાલી, જેમાં ઝરણાં અને ઝરાનું પાણી **વાંસની પાઇપો**થી લેવાય છે. દર મિનિટે આશરે **18-20 લિટર** પાણી વાંસની પાઇપમાં પ્રવેશે છે, સેંકડો મીટર દૂર લઈ જવાય છે, અને છોડ પાસે ઘટીને **દર મિનિટે 20-80 ટીપાં** રહી જાય છે.\n"
  "- **પ્રધાનમંત્રી કૃષિ સિંચાઈ યોજના (2015):** દરેક ખેતર સુધી સિંચાઈ પહોંચાડવા ('**હર ખેત કો પાની**') અને સારી સિંચાઈ તથા જળ સંરક્ષણથી પાણીના ઉપયોગની કાર્યક્ષમતા વધારવા ('**દરેક ટીપે વધુ પાક**')ની કેન્દ્રીય યોજના."),
 "s4.table.title": ("भारत भर में पारंपरिक जल संग्रहण", "ભારતભરમાં પરંપરાગત જળ સંગ્રહ"),
 "s4.table.body": (
  "| क्षेत्र | पारंपरिक विधि |\n|---|---|\n| पश्चिमी हिमालय (पहाड़) | **गुल या कुल**: खेती के लिए वाहिकाएँ |\n| राजस्थान (घर) | पीने के पानी के लिए **छत वर्षा जल संग्रहण** |\n"
  "| बंगाल के बाढ़ के मैदान | खेतों की सिंचाई के लिए **बाढ़ जल वाहिकाएँ** |\n| शुष्क राजस्थान (जैसलमेर और अन्य भाग) | **खादीन** और **जोहड़**: खेतों को वर्षा जल भंडार में बदलना |\n"
  "| बीकानेर, फलोदी, बाड़मेर | **टाँके**: **पालर पानी** इकट्ठा करने वाले भूमिगत टैंक |\n| मेघालय | लगभग 200 वर्ष पुरानी **बाँस ड्रिप सिंचाई** |",
  "| પ્રદેશ | પરંપરાગત પદ્ધતિ |\n|---|---|\n| પશ્ચિમ હિમાલય (પહાડો) | **ગુલ કે કુલ**: ખેતી માટેની નાળો |\n| રાજસ્થાન (ઘરો) | પીવાના પાણી માટે **છાપરા વરસાદી જળ સંગ્રહ** |\n"
  "| બંગાળનાં પૂરનાં મેદાનો | ખેતરોની સિંચાઈ માટે **પૂરના પાણીની નહેરો** |\n| શુષ્ક રાજસ્થાન (જેસલમેર અને અન્ય ભાગો) | **ખડીન** અને **જોહડ**: ખેતરોને વરસાદી જળ સંગ્રહમાં ફેરવવાં |\n"
  "| બિકાનેર, ફલોદી, બાડમેર | **ટાંકાં**: **પાલર પાણી** સંગ્રહતી ભૂગર્ભ ટાંકીઓ |\n| મેઘાલય | આશરે 200 વર્ષ જૂની **વાંસ ટપક સિંચાઈ** |"),
 "s5.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s5.memory.body": (
  "- **जल का हिस्सा: \"96.5 समुद्र, 2.5 मीठा\"**; मीठे जल में 70% बर्फ़, 30% से कम भौम जल।\n- **दो आदर्श परियोजनाएँ: \"भाखड़ा = बिजली + भूमि (विद्युत + सिंचाई); हीराकुड = बाढ़ रोके\"।**\n"
  "- **मानचित्र के बाँध, उत्तर से दक्षिण: \"स-भा-टि-रा-स-ही-ना-तुं\"** = सलाल, भाखड़ा नांगल, टिहरी, राणा प्रताप सागर, सरदार सरोवर, हीराकुड, नागार्जुन सागर, तुंगभद्रा।\n"
  "- **क्षेत्र के अनुसार संग्रहण:** हिमालय = गुल/कुल; बंगाल = बाढ़ जल वाहिकाएँ; राजस्थान = खादीन, जोहड़, टाँके; मेघालय = बाँस ड्रिप।\n- **तमिलनाडु = छत संग्रहण अनिवार्य करने वाला पहला राज्य।**",
  "- **પાણીનો હિસ્સો: \"96.5 દરિયો, 2.5 મીઠું\"**; મીઠા પાણીમાં 70% બરફ, 30%થી ઓછું ભૂગર્ભજળ.\n- **બે આદર્શ યોજનાઓ: \"ભાખરા = વીજળી + ખેતી (વિદ્યુત + સિંચાઈ); હીરાકુડ = પૂર રોકે\".**\n"
  "- **નકશાના બંધો, ઉત્તરથી દક્ષિણ: \"સ-ભા-ટિ-રા-સ-હી-ના-તું\"** = સલાલ, ભાખરા નાંગલ, ટિહરી, રાણા પ્રતાપ સાગર, સરદાર સરોવર, હીરાકુડ, નાગાર્જુન સાગર, તુંગભદ્રા.\n"
  "- **પ્રદેશ મુજબ સંગ્રહ:** હિમાલય = ગુલ/કુલ; બંગાળ = પૂરના પાણીની નહેરો; રાજસ્થાન = ખડીન, જોહડ, ટાંકાં; મેઘાલય = વાંસ ટપક.\n- **તમિળનાડુ = છાપરા સંગ્રહ ફરજિયાત કરનાર પહેલું રાજ્ય.**"),
 "s5.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s5.mistakes.body": (
  "1. कहना कि जल दुर्लभता केवल वहीं होती है जहाँ वर्षा नहीं होती: यह **अति-उपयोग, असमान पहुँच और प्रदूषण** से भी होती है।\n2. भाखड़ा नांगल (**सतलुज**, विद्युत और सिंचाई) और हीराकुड (**महानदी**, बाढ़ नियंत्रण) को मिलाना।\n"
  "3. कहना कि पहली बारिश का पानी टाँकों में भरा जाता है: वह **इकट्ठा नहीं** किया जाता; उससे छत और पाइप साफ़ होते हैं।\n4. सरदार सरोवर को महानदी पर बताना: यह गुजरात में **नर्मदा** पर है।\n"
  "5. कहना कि राजस्थान ने छत संग्रहण अनिवार्य किया: यह **तमिलनाडु** ने किया।\n6. कहना कि कृष्णा-गोदावरी विवाद नर्मदा को लेकर था: यह **कोयना पर महाराष्ट्र द्वारा जल मोड़ने** को लेकर था, जिसका कर्नाटक और आंध्र प्रदेश ने विरोध किया।",
  "1. કહેવું કે પાણીની અછત ફક્ત જ્યાં વરસાદ ન પડે ત્યાં જ થાય: તે **વધુ પડતા ઉપયોગ, અસમાન પહોંચ અને પ્રદૂષણ**થી પણ થાય છે.\n2. ભાખરા નાંગલ (**સતલુજ**, વિદ્યુત અને સિંચાઈ) અને હીરાકુડ (**મહાનદી**, પૂર નિયંત્રણ)ને ભેળવવા.\n"
  "3. કહેવું કે પહેલા વરસાદનું પાણી ટાંકામાં ભરાય છે: તે **સંગ્રહાતું નથી**; તેનાથી છાપરું અને પાઇપ સાફ થાય છે.\n4. સરદાર સરોવરને મહાનદી પર કહેવો: તે ગુજરાતમાં **નર્મદા** પર છે.\n"
  "5. કહેવું કે રાજસ્થાને છાપરા સંગ્રહ ફરજિયાત કર્યો: તે **તમિળનાડુ**એ કર્યો.\n6. કહેવું કે કૃષ્ણા-ગોદાવરી વિવાદ નર્મદા અંગે હતો: તે **કોયના પર મહારાષ્ટ્રે પાણી વાળવા** અંગે હતો, જેનો કર્ણાટક અને આંધ્ર પ્રદેશે વિરોધ કર્યો."),
 "s5.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s5.tip.body": (
  "स्कूल की छत का क्षेत्रफल और अपने नगर की वार्षिक वर्षा मापें, और गणना करें कि छत से कितने लीटर पानी इकट्ठा हो सकता है (क्षेत्रफल वर्ग मीटर में × वर्षा मिमी में = लीटर)। "
  "फिर विद्यार्थियों से भारत के रेखा-मानचित्र पर आठों बाँध उनकी नदियों के साथ अंकित करवाएँ।",
  "શાળાના છાપરાનું ક્ષેત્રફળ અને તમારા નગરનો વાર્ષિક વરસાદ માપો, અને ગણો કે છાપરા પરથી કેટલા લિટર પાણી સંગ્રહી શકાય (ક્ષેત્રફળ ચો. મીટરમાં × વરસાદ મિમીમાં = લિટર). "
  "પછી વિદ્યાર્થીઓ પાસે ભારતના રેખાનકશામાં આઠેય બંધો તેમની નદીઓ સાથે દર્શાવડાવો."),
 "s5.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s5.reflection.body": (
  "नेहरू ने बाँधों को 'आधुनिक भारत के मंदिर' कहा, जबकि इनसे विस्थापित लोगों ने विरोध किया। बड़े बाँधों के पक्ष में एक और वर्षा जल संग्रहण के पक्ष में एक तर्क लिखिए, और बताइए कि आपके क्षेत्र के लिए कौन-सा बेहतर है।",
  "નેહરુએ બંધોને 'આધુનિક ભારતનાં મંદિરો' કહ્યા, જ્યારે તેનાથી વિસ્થાપિત લોકોએ વિરોધ કર્યો. મોટા બંધોની તરફેણમાં એક અને વરસાદી જળ સંગ્રહની તરફેણમાં એક દલીલ લખો, અને જણાવો કે તમારા પ્રદેશ માટે કયું વધુ યોગ્ય છે."),
 "s5.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s5.connection.body": (
  "- **अध्याय 1:** अति सिंचाई से जलाक्रांतता और लवणता होती है।\n- **अध्याय 2:** नर्मदा सागर जैसे बाँध वनों को डुबोते हैं।\n"
  "- **अध्याय 4 (कृषि):** सिंचाई और शस्य प्रतिरूप।\n- **अध्याय 5 (ऊर्जा):** बहुउद्देशीय परियोजनाओं से जलविद्युत।",
  "- **પ્રકરણ 1:** અતિસિંચાઈથી જમીન પાણીથી ભરાય છે અને ક્ષારતા વધે છે.\n- **પ્રકરણ 2:** નર્મદા સાગર જેવા બંધો જંગલો ડુબાડે છે.\n"
  "- **પ્રકરણ 4 (કૃષિ):** સિંચાઈ અને પાક ભાત.\n- **પ્રકરણ 5 (ઊર્જા):** બહુહેતુક યોજનાઓમાંથી જળવિદ્યુત."),
 "s5.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s5.mastery.body": (
  "'बहुउद्देशीय नदी परियोजनाएँ वरदान भी हैं और अभिशाप भी।' लगभग 120 शब्दों में समझाइए।\n\n"
  "**आदर्श उत्तर:** भाखड़ा नांगल और हीराकुड जैसी बहुउद्देशीय परियोजनाएँ सिंचाई, जलविद्युत, घरों और उद्योगों के लिए जल, बाढ़ नियंत्रण, नौचालन, मछली पालन और मनोरंजन देती हैं, इसलिए नेहरू ने बाँधों को आधुनिक भारत के मंदिर कहा। "
  "पर ये नदियों का प्राकृतिक बहाव रोकती हैं, तलछट और चट्टानी नदी तल बनाती हैं, नदियों को टुकड़ों में बाँटती हैं जिससे मछलियाँ अंडे देने के लिए नहीं जा पातीं, और वनों और मिट्टी को डुबोती हैं। "
  "ये स्थानीय लोगों को विस्थापित करती हैं, जिसका नर्मदा बचाओ आंदोलन ने विरोध किया, और कृष्णा-गोदावरी जैसे अंतर्राज्यीय विवाद पैदा करती हैं। कभी-कभी तलछट और अचानक पानी छोड़ने से बाढ़ भी आती है, और जल-सघन फ़सलों से लवणीकरण होता है। "
  "इसलिए हमें इनके लाभों और लागतों को तौलना चाहिए और इन्हें वर्षा जल संग्रहण के साथ जोड़ना चाहिए।",
  "'બહુહેતુક નદી યોજનાઓ વરદાન પણ છે અને અભિશાપ પણ.' આશરે 120 શબ્દોમાં સમજાવો.\n\n"
  "**આદર્શ ઉત્તર:** ભાખરા નાંગલ અને હીરાકુડ જેવી બહુહેતુક યોજનાઓ સિંચાઈ, જળવિદ્યુત, ઘરો અને ઉદ્યોગો માટે પાણી, પૂર નિયંત્રણ, જળ પરિવહન, મત્સ્ય ઉછેર અને મનોરંજન આપે છે, તેથી નેહરુએ બંધોને આધુનિક ભારતનાં મંદિરો કહ્યા. "
  "પણ તે નદીઓનો કુદરતી પ્રવાહ રોકે છે, કાંપ અને ખડકાળ નદીતળ સર્જે છે, નદીઓને ટુકડાઓમાં વહેંચે છે જેથી માછલીઓ ઈંડાં મૂકવા જઈ શકતી નથી, અને જંગલો અને જમીન ડુબાડે છે. "
  "તે સ્થાનિક લોકોને વિસ્થાપિત કરે છે, જેનો નર્મદા બચાવો આંદોલને વિરોધ કર્યો, અને કૃષ્ણા-ગોદાવરી જેવા આંતરરાજ્ય વિવાદો સર્જે છે. ક્યારેક કાંપ અને અચાનક પાણી છોડવાથી પૂર પણ આવે છે, અને પાણી માગતા પાકોથી ક્ષારીકરણ થાય છે. "
  "તેથી આપણે તેના લાભો અને ખર્ચ તોલવા જોઈએ અને તેને વરસાદી જળ સંગ્રહ સાથે જોડવી જોઈએ."),
 "s5.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s5.summary.body": (
  "- विश्व के जल का केवल लगभग 2.5% अलवणीय है; दुर्लभता जनसंख्या, सिंचाई, भौम जल के अति-उपयोग, उद्योग, शहरों, असमान पहुँच और प्रदूषण से होती है।\n"
  "- भारत में प्राचीन जलीय कृतियाँ थीं: श्रिंगवेरा (ईसा पूर्व पहली शताब्दी), भोपाल झील (11वीं शताब्दी) और हौज़ ख़ास तालाब (14वीं शताब्दी, इल्तुतमिश)।\n"
  "- बहुउद्देशीय परियोजनाएँ (भाखड़ा नांगल, हीराकुड) अनेक उपयोग देती हैं पर पारिस्थितिक हानि, विस्थापन, विवाद और बाढ़ भी लाती हैं।\n"
  "- पारंपरिक वर्षा जल संग्रहण: गुल/कुल, छत संग्रहण, बाढ़ जल वाहिकाएँ, खादीन, जोहड़, टाँके; मेघालय में बाँस ड्रिप सिंचाई।\n"
  "- आधुनिक प्रयास: गेंदाथूर, शिलांग, तमिलनाडु का अनिवार्य छत संग्रहण और PMKSY (2015)।",
  "- વિશ્વના પાણીનો ફક્ત આશરે 2.5% મીઠું છે; અછત વસ્તી, સિંચાઈ, ભૂગર્ભજળના વધુ પડતા ઉપયોગ, ઉદ્યોગ, શહેરો, અસમાન પહોંચ અને પ્રદૂષણથી થાય છે.\n"
  "- ભારતમાં પ્રાચીન જળ માળખાં હતાં: શ્રૃંગવેરપુર (ઈ.સ. પૂર્વે પહેલી સદી), ભોપાલ તળાવ (11મી સદી) અને હૌઝ ખાસ તળાવ (14મી સદી, ઇલ્તુત્મિશ).\n"
  "- બહુહેતુક યોજનાઓ (ભાખરા નાંગલ, હીરાકુડ) અનેક ઉપયોગો આપે છે પણ પર્યાવરણીય નુકસાન, વિસ્થાપન, વિવાદો અને પૂર પણ લાવે છે.\n"
  "- પરંપરાગત વરસાદી જળ સંગ્રહ: ગુલ/કુલ, છાપરા સંગ્રહ, પૂરના પાણીની નહેરો, ખડીન, જોહડ, ટાંકાં; મેઘાલયમાં વાંસ ટપક સિંચાઈ.\n"
  "- આધુનિક પ્રયાસો: ગેંડાથુર, શિલોંગ, તમિળનાડુનો ફરજિયાત છાપરા સંગ્રહ અને PMKSY (2015)."),
 "s5.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s5.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में पूछा गया कि किस राज्य ने छत संग्रहण अनिवार्य किया (तमिलनाडु), PMKSY का लक्ष्य (किसानों के लिए बेहतर सिंचाई और सतत जल संरक्षण), और मानचित्र पर भाखड़ा नांगल या हीराकुड दिखाने को कहा गया।\n"
  "- 3/5 अंक के प्रिय प्रश्न: जल दुर्लभता के कारण, बहुउद्देशीय परियोजनाओं के लाभ और समस्याएँ, राजस्थान और मेघालय में वर्षा जल संग्रहण।\n"
  "- **मानचित्र कार्य:** सलाल, भाखड़ा नांगल, टिहरी, राणा प्रताप सागर, सरदार सरोवर, हीराकुड, नागार्जुन सागर और तुंगभद्रा को दिखाइए।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં પૂછાયું કે કયા રાજ્યે છાપરા સંગ્રહ ફરજિયાત કર્યો (તમિળનાડુ), PMKSYનું લક્ષ્ય (ખેડૂતો માટે સારી સિંચાઈ અને ટકાઉ જળ સંરક્ષણ), અને નકશામાં ભાખરા નાંગલ કે હીરાકુડ દર્શાવવા કહેવાયું.\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: પાણીની અછતનાં કારણો, બહુહેતુક યોજનાઓના લાભ અને સમસ્યાઓ, રાજસ્થાન અને મેઘાલયમાં વરસાદી જળ સંગ્રહ.\n"
  "- **નકશા કાર્ય:** સલાલ, ભાખરા નાંગલ, ટિહરી, રાણા પ્રતાપ સાગર, સરદાર સરોવર, હીરાકુડ, નાગાર્જુન સાગર અને તુંગભદ્રા દર્શાવો."),
 "s5.flash1.front": ("टाँके क्या हैं?", "ટાંકાં શું છે?"),
 "s5.flash1.back": ("राजस्थान (बीकानेर, फलोदी, बाड़मेर) के भूमिगत टैंक, जिनमें छत का वर्षा जल (पालर पानी) इकट्ठा होता है।", "રાજસ્થાન (બિકાનેર, ફલોદી, બાડમેર)ની ભૂગર્ભ ટાંકીઓ, જેમાં છાપરાનું વરસાદી પાણી (પાલર પાણી) સંગ્રહાય છે."),
 "s5.flash2.front": ("भाखड़ा नांगल और हीराकुड के दो-दो उपयोग बताइए।", "ભાખરા નાંગલ અને હીરાકુડના બે-બે ઉપયોગો જણાવો."),
 "s5.flash2.back": ("भाखड़ा नांगल: जलविद्युत और सिंचाई। हीराकुड: जल संरक्षण और बाढ़ नियंत्रण।", "ભાખરા નાંગલ: જળવિદ્યુત અને સિંચાઈ. હીરાકુડ: જળ સંરક્ષણ અને પૂર નિયંત્રણ."),
 "s5.flash3.front": ("नर्मदा बचाओ आंदोलन ने किसका विरोध किया?", "નર્મદા બચાવો આંદોલને શાનો વિરોધ કર્યો?"),
 "s5.flash3.back": ("सरदार सरोवर बाँध का: पहले उसकी पर्यावरणीय हानि का, बाद में विस्थापितों के ख़राब पुनर्वास का।", "સરદાર સરોવર બંધનો: પહેલાં તેના પર્યાવરણીય નુકસાનનો, પછી વિસ્થાપિતોના નબળા પુનર્વસનનો."),
 "s5.flash4.front": ("बाँस ड्रिप सिंचाई कैसे काम करती है?", "વાંસ ટપક સિંચાઈ કેવી રીતે કામ કરે છે?"),
 "s5.flash4.back": ("बाँस के पाइप झरनों से प्रति मिनट 18-20 लीटर पानी लाते हैं; पौधे तक यह 20-80 बूँद प्रति मिनट रह जाता है।", "વાંસની પાઇપો ઝરામાંથી દર મિનિટે 18-20 લિટર પાણી લાવે છે; છોડ સુધી તે દર મિનિટે 20-80 ટીપાં રહી જાય છે."),
}
